<?php require 'config/config.php'; require_role('customer'); if($_SERVER['REQUEST_METHOD']!=='POST')redirect('products.php');check_csrf();$pid=(int)$_POST['product_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$s=db()->prepare("INSERT INTO reviews(product_id,customer_id,rating,comment,review_date) VALUES(?,?,?,?,NOW())");$s->execute([$pid,user()['id'],$rating,$comment]);flash('success','Review submitted.');redirect('product.php?id='.$pid);?>